        ok: false,
        fatal: true,
        detail: `MCP transport returned internal HTTP 502 for ${failure.attrs.rpc_method} at ${failure.time}`,
      };
    } catch (error) {
      return {
        observed: false,
        ok: false,
        fatal: false,
